#!/usr/bin/env node
// Build Integrity Gate (CI-001).
//
// Run AFTER a clean `npm run build` + `npm run build:ui`. Fails (exit 1) if the
// tracked `dist/` differs in ANY way from what the sources just produced:
// modified, deleted, staged, or untracked-but-generated files.
//
// Read-only: only `git status` is executed. It never adds, resets, cleans or
// rewrites anything, and it does not "fix" drift.
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const LABELS = {
  '??': 'UNTRACKED  (generated by build, missing from git)',
  M: 'MODIFIED   (tracked artifact differs from build output)',
  D: 'DELETED    (tracked artifact is no longer produced by the build)',
  A: 'ADDED      (staged, differs from HEAD)',
  R: 'RENAMED',
  C: 'COPIED',
  T: 'TYPECHANGE',
  U: 'CONFLICT',
};

/**
 * Parse `git status --porcelain=v1 -z` output into [{ code, path }].
 * Exported for tests.
 */
export function parsePorcelainZ(out) {
  const parts = out.split('\0');
  const entries = [];
  for (let i = 0; i < parts.length; i++) {
    const rec = parts[i];
    if (rec.length < 4) continue; // trailing empty record
    const x = rec[0];
    const y = rec[1];
    const path = rec.slice(3);
    const code = x === '?' ? '??' : (y !== ' ' ? y : x);
    entries.push({ code, path });
    // Rename/copy records carry the origin path as an extra NUL field.
    if (x === 'R' || x === 'C' || y === 'R' || y === 'C') i++;
  }
  return entries;
}

/** Return every drifting path under `dir`, relative to the git root `root`. */
export function findDrift(root, dir = 'dist') {
  const out = execFileSync(
    'git',
    ['-C', root, 'status', '--porcelain=v1', '-z', '--untracked-files=all', '--', dir],
    { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 },
  );
  return parsePorcelainZ(out);
}

function main() {
  const root = process.argv[2] ?? process.cwd();
  let drift;
  try {
    drift = findDrift(root);
  } catch (err) {
    console.error(`Build Integrity Gate: cannot run git status in ${root}: ${err.message}`);
    process.exit(2);
  }
  if (drift.length === 0) {
    console.log('Build Integrity Gate: PASS — tracked dist/ matches the build output.');
    return;
  }
  console.error(`Build Integrity Gate: FAIL — ${drift.length} path(s) under dist/ drift from the sources:\n`);
  for (const { code, path } of drift) {
    console.error(`  ${(LABELS[code] ?? code).padEnd(58)} ${path}`);
  }
  console.error(
    '\nNote: this gate compares the working tree with what is COMMITTED. CI runs it after a\n' +
      'fresh checkout + clean rebuild, so it verifies committed artifacts. Before the\n' +
      'synchronized dist/ is first committed, local drift is expected; the gate must pass\n' +
      'once the regenerated dist/ is committed.\n' +
      'To fix: remove dist/ and tsconfig.tsbuildinfo, run `pnpm run build && pnpm run build:ui`,\n' +
      'review the diff, and commit the regenerated dist/. CI never fixes drift automatically.',
  );
  process.exit(1);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main();
